let state;const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rows=x=>(x||[]).map(r=>r.map(c=>c[1]??'NULL').join(' | ')).join('\n');
const reason={source_integrity_failed:'The source database failed an integrity check. This result remains unfinished.',source_recovery:'Resolved from a scoped source instruction.',outcome_agreement:'The checked interpretations give the same current table.',user_answer:'Completed using your answer for this scope.',shared_answer:'Completed using the same registered answer.',unresolved_interpretation:'The meaning still needs a decision.',verification_failed:'A candidate failed checking. Agreement is not established.',unsupported_preparation:'No supported implementation is available.',global_wait:'Waiting for the rest of the project.',full_context_proposal:'Released the first executable proposal.',answer_execution_failed:'The chosen implementation failed. Work remains unfinished.'};
function render(){document.querySelector('#budget').innerHTML=`<div><strong>${state.answers_remaining}</strong> answer units left</div><div><strong>${state.checks_remaining}</strong> machine checks left</div>`;document.querySelector('#changed').textContent=state.changes.length?'Changed inputs: recheck '+state.changes.join(', ')+'.':'';document.querySelector('#work').innerHTML=state.work.map(w=>`<article class="card"><span class="status ${w.status}">${esc(w.status.replaceAll('_',' '))}</span><div class="role">${esc(w.agent)}</div><h3>${esc(w.title)}</h3><p>${esc(w.request)}</p><p class="scope">Scope: ${esc(w.scope)}</p><div class="reason">${esc(reason[w.reason]||w.reason)}</div>${w.rows?'<div class="preview">'+esc(rows(w.rows))+'</div>':''}<details><summary>Sources and version</summary><p>Version ${w.version}</p>${w.source.length?w.source.map(s=>'<blockquote>'+esc(s.text)+'</blockquote>').join(''):'<p>No explicit definition has been supplied for this scope.</p>'}</details>${w.id!=='inventory'&&w.status==='released'?`<button class="reconsider" onclick="action({action:'reconsider',task:'${esc(w.id)}'})">Reconsider this definition</button>`:''}</article>`).join('');let q=state.question,e=document.querySelector('#question');e.className=q?'active':'';e.innerHTML=q?`<p class="eyebrow">A decision remains</p><h2>${esc(q.text)}</h2><p>This answer applies to <strong>${esc(q.scope)}</strong> and covers ${q.affected.map(esc).join(', ')}.</p><div class="options">${q.candidates.slice(0,2).map(c=>'<div class="option"><strong>'+esc(c.meaning)+'</strong><pre>'+esc(rows(c.preview)||c.outcome.error||'Empty result')+'</pre></div>').join('')}</div><div class="choices"><button class="primary" onclick="answer('spending')">Use spending at least 100</button><button class="primary" onclick="answer('orders')">Use at least 3 orders</button><button onclick="action({action:'defer'})">Leave unresolved (1 unit)</button></div><label><input type="checkbox" id="narrow"> Apply only to this request (one extra scope decision)</label><p class="small">Already able to continue: ${q.remaining_work.map(esc).join(', ')||'No other result is ready yet'}.</p><details><summary>Inspect candidate queries</summary><pre>${esc(JSON.stringify(q.candidates.map(c=>({meaning:c.meaning,sql:c.sql,status:c.outcome.status})),null,2))}</pre></details>`:'<p class="small">Use “Check what needs me” to inspect the next consequential question. Released work remains available while other requests wait.</p>';document.querySelector('#events').textContent=JSON.stringify(state.events,null,2)}
async function action(a){document.querySelector('#error').textContent='';let r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(a)});let x=await r.json();if(!r.ok){document.querySelector('#error').textContent=x.error;return x}state=x;render();return x}
async function answer(value){return action({action:'answer',value,only_this_request:document.querySelector('#narrow').checked})}
fetch('/api/state').then(r=>r.json()).then(x=>{state=x;render()});
